package com.dy.artisan3d.ui.screen.products.listimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport androidx.paging.PagingDataimport androidx.paging.cachedInimport com.dy.artisan3d.data.AppLanguageimport com.dy.artisan3d.domain.model.Productimport com.dy.artisan3d.domain.repository.ProductRepositoryimport kotlinx.coroutines.flow.Flowclass ProductListViewModel(    private val repository: ProductRepository,    private val appLang: AppLanguage,    private val categoryId: Int?,    private val brandId: Int?,    val title: String,) : ViewModel() {    val products: Flow<PagingData<Product>> = repository        .getProductsPager(categoryId ?: 0, brandId = brandId ?: 0, appLang.current)        .cachedIn(viewModelScope)}